#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Issue #46 (0verlabs/herald): probe sponsored MPC sign through NEP-366 on
# testnet. The human signs in to a local Herald testnet dashboard with Meteor
# Wallet and runs two checks on the throwaway probe page
# (apps/web/src/routes/_dashboard/sponsored-sign-probe.tsx):
#   one    Meteor signs 1 delegate action holding one MPC `sign` call
#   three  Meteor signs 3 delegate actions in one signDelegateActions request
# Each delegate action holds one `sign` call to v1.signer-prod.testnet (path
# herald-sponsored-probe, domain 1, 50 Tgas, 1 yoctoNEAR). The page's server
# function relays them with Herald's testnet relayer key, waits for them to be
# final, verifies the MPC signatures and shows a result line to copy back.
# The wizard writes the Meteor section of docs/research/sponsored-mpc-sign.md
# and posts it on #46.
#
# Answers persist in .env.sponsored-sign-probe (gitignored), so a re-run
# offers them back. Nothing there is secret and nothing goes to GitHub
# secrets. The relayer's private key is only copied, by node, from its key
# file in ~/.near-credentials into apps/web/.dev.vars (gitignored) as
# PROBE_NEAR_RELAYER_KEY, and removed from there at the end. It is never
# printed, never passed as a command argument and never held in a shell
# variable.

APP_URL="http://localhost:3000"
REPO="0verlabs/herald"
ISSUE=46
FINDINGS="docs/research/sponsored-mpc-sign.md"
ADR="docs/adr/0010-sponsored-mpc-sign-nep-366.md"
PROBE_ROUTE="apps/web/src/routes/_dashboard/sponsored-sign-probe.tsx"
PROBE_SERVER="apps/web/src/server/sponsored-sign-probe.ts"
ROUTE_TREE="apps/web/src/routeTree.gen.ts"
RELAYER_ENV=".env.near-relayer"
DEV_VARS="apps/web/.dev.vars"
PROBE_KEY_NAME="PROBE_NEAR_RELAYER_KEY"
MARKER_START="<!-- meteor-run:start -->"
MARKER_END="<!-- meteor-run:end -->"
EXPLORER="https://testnet.nearblocks.io"

# field KEY LINE: the value of KEY=... in a probe result line.
field() {
  local re="(^| )$1=([^ ]*)"
  if [[ "$2" =~ $re ]]; then printf '%s' "${BASH_REMATCH[2]}"; fi
}

# error_of LINE: everything after " error=", the last field of a result line.
error_of() {
  if [[ "$1" == *" error="* ]]; then printf '%s' "${1#* error=}"; fi
}

# saved KEY: what this run (or an earlier one) recorded for KEY.
saved() { _existing "$1" || true; }

gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# slug_of CHECK / size_of CHECK: env key part and delegate count of a check.
slug_of() { if [[ "$1" == one ]]; then printf ONE; else printf THREE; fi; }
size_of() { if [[ "$1" == one ]]; then printf 1; else printf 3; fi; }

# esc TEXT: TEXT made safe for a markdown table cell.
esc() { local s="$1"; s=${s//|/\\|}; printf '%s' "$s"; }

# val VALUE [UNIT]: VALUE (with UNIT), or "not read" when the page had none.
val() {
  if [[ -z "$1" || "$1" == "-" ]]; then printf 'not read'; else printf '%s%s' "$1" "${2:+ $2}"; fi
}

# relayer_account: the testnet relayer's account id from .env.near-relayer.
relayer_account() {
  local ENV_FILE="$RELAYER_ENV"
  _existing NEAR_RELAYER_ACCOUNT_TESTNET
}

# key_file ACCOUNT: where the relayer's key file lives on this machine.
key_file() { printf '%s/.near-credentials/testnet/%s.json' "$HOME" "$1"; }

# public_key_of FILE: the public key of a key file (safe to show).
public_key_of() {
  node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(process.argv[1], "utf8")).public_key)' "$1"
}

# install_probe_key FILE ACCOUNT: node reads the private key from FILE and
# upserts PROBE_NEAR_RELAYER_KEY=<key> into apps/web/.dev.vars, keeping the
# other lines. The key never reaches the shell.
install_probe_key() {
  node -e '
    const fs = require("node:fs");
    const [keyFile, account, devVars, name] = process.argv.slice(1);
    const file = JSON.parse(fs.readFileSync(keyFile, "utf8"));
    const key = file.private_key;
    if (file.account_id !== account) {
      console.error("The key file is for " + file.account_id + ", not " + account + ".");
      process.exit(1);
    }
    if (typeof key !== "string" || !/^ed25519:[1-9A-HJ-NP-Za-km-z]+$/.test(key)) {
      console.error("The key file has no ed25519 private_key.");
      process.exit(1);
    }
    const old = fs.existsSync(devVars) ? fs.readFileSync(devVars, "utf8") : "";
    let out = old.split("\n").filter((l) => !l.startsWith(name + "=")).join("\n");
    if (out !== "" && !out.endsWith("\n")) out += "\n";
    fs.writeFileSync(devVars, out + name + "=" + key + "\n", { mode: 0o600 });
  ' "$1" "$2" "$DEV_VARS" "$PROBE_KEY_NAME"
}

# remove_probe_key: node drops the PROBE_NEAR_RELAYER_KEY line from
# apps/web/.dev.vars, keeping the other lines.
remove_probe_key() {
  node -e '
    const fs = require("node:fs");
    const [devVars, name] = process.argv.slice(1);
    if (!fs.existsSync(devVars)) process.exit(0);
    const old = fs.readFileSync(devVars, "utf8");
    fs.writeFileSync(devVars, old.split("\n").filter((l) => !l.startsWith(name + "=")).join("\n"));
  ' "$DEV_VARS" "$PROBE_KEY_NAME"
}

has_probe_key() { [[ -f "$DEV_VARS" ]] && grep -q "^${PROBE_KEY_NAME}=" "$DEV_VARS"; }

# nonces_distinct LINE N: the line lists N nonces and no two are equal.
nonces_distinct() {
  local list i j
  local -a ns=()
  list=$(field nonces "$1")
  if [[ -z "$list" || "$list" == "-" ]]; then return 1; fi
  IFS=',' read -r -a ns <<<"$list"
  if (( ${#ns[@]} != $2 )); then return 1; fi
  for ((i = 0; i < ${#ns[@]}; i++)); do
    if [[ -z "${ns[i]}" ]]; then return 1; fi
    for ((j = i + 1; j < ${#ns[@]}; j++)); do
      if [[ "${ns[i]}" == "${ns[j]}" ]]; then return 1; fi
    done
  done
  return 0
}

# passes CHECK: everything landed and verified, and for check three each
# delegate action had its own nonce. The approval count is judged apart
# (one_approval): it decides the UX, not whether sponsoring works.
passes() {
  local slug n line
  slug=$(slug_of "$1"); n=$(size_of "$1")
  line=$(saved "PROBE_${slug}_LINE")
  [[ -n "$line" && "$(field outcome "$line")" == ok && "$(field signatures "$line")" == "$n/$n" ]] || return 1
  if [[ "$1" == three ]]; then nonces_distinct "$line" 3 || return 1; fi
  return 0
}

# one_approval CHECK: the human counted exactly one approval prompt.
one_approval() { [[ "$(saved "PROBE_$(slug_of "$1")_PROMPTS")" == 1 ]]; }

# nonces_ascending LINE: the wallet numbered the nonces in request order,
# lowest first. Then the first delegate action asked for (Solana's, in
# "Sweep all") is the first one the relayer can send.
nonces_ascending() {
  local list prev="" n
  local -a ns=()
  list=$(field nonces "$1")
  [[ -n "$list" && "$list" != "-" ]] || return 1
  IFS=',' read -r -a ns <<<"$list"
  for n in "${ns[@]}"; do
    [[ "$n" =~ ^[0-9]+$ ]] || return 1
    if [[ -n "$prev" ]] && ! node -e 'process.exit(BigInt(process.argv[1]) > BigInt(process.argv[2]) ? 0 : 1)' "$n" "$prev"; then
      return 1
    fi
    prev="$n"
  done
}

# summary CHECK: one line describing what a check recorded.
summary() {
  local slug line prompts err out
  slug=$(slug_of "$1"); line=$(saved "PROBE_${slug}_LINE")
  if [[ -z "$line" ]]; then printf 'not run'; return 0; fi
  prompts=$(saved "PROBE_${slug}_PROMPTS"); err=$(error_of "$line")
  out="outcome $(field outcome "$line"), landed $(field landed "$line"), signatures $(field signatures "$line")"
  out+=", nonces $(field nonces "$line"), key $(field key "$line"), ${prompts:-?} approval prompt(s)"
  if [[ -n "$err" ]]; then out+=", error: $err"; fi
  printf '%s' "$out"
}

tx_text() {
  case "$1" in
    empty) printf 'an empty SuccessValue, so the signature is only in a receipt' ;;
    value) printf 'a SuccessValue with a value' ;;
    failure) printf 'a failure' ;;
    mixed) printf 'mixed across the transactions' ;;
    *) printf 'not read' ;;
  esac
}

# answer_q1: MPC answers a relayed sign, and Herald reads it (check one).
answer_q1() {
  local line sigs err
  line=$(saved PROBE_ONE_LINE)
  if [[ -z "$line" ]]; then printf 'Not run.'; return 0; fi
  sigs=$(field signatures "$line"); err=$(error_of "$line")
  if [[ "$sigs" == 1/1 ]]; then printf 'Yes. '; else printf 'No. '; fi
  printf 'MPC signatures read from receipts and verified: %s. Delegate receipts that succeeded: %s. Top-level status of the relayer transaction: %s.' \
    "$(val "$sigs")" "$(val "$(field landed "$line")")" "$(tx_text "$(field tx_status "$line")")"
  if [[ -n "$err" ]]; then printf ' Error: %s' "$(esc "$err")"; fi
}

# answer_q2: Meteor signs a delegate action with the 1 yoctoNEAR deposit (check one).
answer_q2() {
  local line err
  line=$(saved PROBE_ONE_LINE)
  if [[ -z "$line" ]]; then printf 'Not run.'; return 0; fi
  err=$(error_of "$line")
  if [[ "$(field landed "$line")" == 1/1 ]]; then printf 'Yes. '; else printf 'No. '; fi
  printf 'Manifest declares `signDelegateActions`: %s. Deposit on the `sign` call: %s. Signing key: %s. Validity window (`max_block_height` minus the final height just before signing): %s. Blocks left when Herald received it: %s. Approval prompts: %s. Provider Account balance change across the relay: %s.' \
    "$(val "$(field feature "$line")")" "$(val "$(field deposit "$line")" yoctoNEAR)" \
    "$(val "$(field key "$line")")" "$(val "$(field window_blocks "$line")" blocks)" \
    "$(val "$(field valid_blocks "$line")")" \
    "$(val "$(saved PROBE_ONE_PROMPTS)")" "$(val "$(field provider_delta "$line")" yoctoNEAR)"
  if [[ -n "$err" ]]; then printf ' Error: %s' "$(esc "$err")"; fi
}

# answer_q3: 3 delegate actions in one request each get a nonce and land (check three).
answer_q3() {
  local line err nonces distinct="not distinct" order="not in request order"
  line=$(saved PROBE_THREE_LINE)
  if [[ -z "$line" ]]; then printf 'Not run.'; return 0; fi
  err=$(error_of "$line"); nonces=$(field nonces "$line")
  if nonces_distinct "$line" 3; then distinct="distinct"; fi
  if nonces_ascending "$line"; then order="ascending in request order"; fi
  if [[ "$distinct" == distinct && "$(field landed "$line")" == 3/3 ]]; then printf 'Yes. '; else printf 'No. '; fi
  printf 'Nonces: %s (%s, %s). Delegate receipts that succeeded: %s. MPC signatures verified: %s. Signing public keys: %s. Approval prompts: %s.' \
    "$(val "${nonces//,/, }")" "$distinct" "$order" "$(val "$(field landed "$line")")" \
    "$(val "$(field signatures "$line")")" "$(val "$(field keys "$line")")" "$(val "$(saved PROBE_THREE_PROMPTS)")"
  if [[ -n "$err" ]]; then printf ' Error: %s' "$(esc "$err")"; fi
}

# probe_check CHECK: run one check on the probe page and record it.
probe_check() {
  local check="$1" slug line seen
  slug=$(slug_of "$check")
  local prompts_key="PROBE_${slug}_PROMPTS" line_key="PROBE_${slug}_LINE" note_key="PROBE_${slug}_NOTE"
  if [[ "$check" == one ]]; then
    say "Meteor signs one delegate action holding one MPC sign call."
  else
    say "Meteor signs 3 delegate actions in one request, each holding one MPC sign call."
  fi
  say "Herald's relayer sends them and pays the gas."
  open_url "$APP_URL/sponsored-sign-probe"
  step "Click the \"Check $check\" button."
  step "Approve in Meteor, counting every approval prompt it shows until it stops asking."
  step "If Meteor shows which key it signs with (full access or function call), note it."
  step "Wait for the \"Result line\" card (up to 3 minutes while the MPC network signs), then click Copy."
  printf '\n'
  while :; do
    ask "$prompts_key" "How many approval prompts did Meteor show? (0 if it refused)"
    [[ "${!prompts_key}" =~ ^[0-9]+$ ]] && break
    warn "Enter a number."
  done
  while :; do
    ask "$line_key" "Paste the result line:"
    line="${!line_key}"
    [[ "$(field check "$line")" == "$check" && -n "$(field outcome "$line")" ]] && break
    warn "That isn't a check $check result line. Copy it from the probe page's Result line card."
  done
  seen=$(field wallet "$line")
  if [[ "$seen" != meteor-wallet && "$seen" != unknown ]]; then
    warn "The probe ran on wallet \"$seen\", not meteor-wallet. Re-run if that's the wrong wallet."
  fi
  ask "$note_key" "Anything worth noting, like the key Meteor said it used, its wording or an error? (Enter for none)"
  write_env "$prompts_key" "${!prompts_key}"
  write_env "$line_key" "$line"
  write_env "$note_key" "${!note_key}"
  if passes "$check"; then
    note "✓ Passes: $(summary "$check")"
  else
    warn "Doesn't pass: $(summary "$check")"
  fi
  pause "Press Enter for the next stage"
}

# write_section FILE: the Meteor section of the findings, without markers.
write_section() {
  local version check slug line n hashes h
  local -a hs=()
  version=$(node -p "require('./apps/web/node_modules/@hot-labs/near-connect/package.json').version" 2>/dev/null || echo 0.12.x)
  {
    printf '\n## Meteor Wallet run\n\n'
    printf 'Status: live testnet check for #%s, %s. Run with `scripts/sponsored-sign-probe-wizard.sh` against a local Herald testnet dashboard, Meteor Wallet and `@hot-labs/near-connect` %s. Relayer: `%s`.\n\n' \
      "$ISSUE" "$(date +%Y-%m-%d)" "$version" "$(saved RELAYER_ACCOUNT)"
    printf '| Question | Answer |\n|---|---|\n'
    printf '| 1. Do MPC nodes answer a `sign` inside a relayed delegate action, and can Herald read the signature from the relayer transaction'\''s outcome? (check one) | %s |\n' "$(answer_q1)"
    printf '| 2. Does Meteor'\''s `signDelegateActions` sign a delegate action whose `sign` call carries 1 yoctoNEAR? Which key signs it, and how long does it stay valid? (check one) | %s |\n' "$(answer_q2)"
    printf '| 3. With 3 delegate actions in one `signDelegateActions` request, does each get its own nonce, so all of them land? (check three) | %s |\n\n' "$(answer_q3)"
    printf '### Raw results\n\n'
    for check in one three; do
      slug=$(slug_of "$check"); line=$(saved "PROBE_${slug}_LINE")
      if [[ -z "$line" ]]; then printf -- '- **Check %s:** not run\n' "$check"; continue; fi
      printf -- '- **Check %s** (%s approval prompt(s))' "$check" "$(saved "PROBE_${slug}_PROMPTS")"
      n=$(saved "PROBE_${slug}_NOTE")
      if [[ -n "$n" ]]; then printf ': %s' "$n"; fi
      printf '\n  - `%s`\n' "$line"
      hashes=$(field hashes "$line")
      if [[ -n "$hashes" && "$hashes" != "-" ]]; then
        IFS=',' read -r -a hs <<<"$hashes"
        for h in "${hs[@]}"; do printf '  - [%s](%s/txns/%s)\n' "$h" "$EXPLORER" "$h"; done
      fi
    done
    printf '\n### Verdict\n\n%s\n\n' "$verdict"
  } > "$1"
}

# has_markers: FINDINGS has the start marker, then the end marker, each on its own line.
has_markers() {
  [[ -f "$FINDINGS" ]] || return 1
  awk -v s="$MARKER_START" -v e="$MARKER_END" '
    $0 == s && !a { a = NR }
    $0 == e && a && !b { b = NR }
    END { exit !(a && b) }
  ' "$FINDINGS"
}

# splice_section FILE: replace the lines between the markers with FILE.
splice_section() {
  local tmp
  tmp=$(mktemp "$FINDINGS.XXXXXX")
  awk -v s="$MARKER_START" -v e="$MARKER_END" -v sec="$1" '
    BEGIN { while ((getline l < sec) > 0) body = body l "\n" }
    $0 == s && !done { print; printf "%s", body; skip = 1; done = 1; next }
    skip && $0 == e { skip = 0 }
    !skip { print }
  ' "$FINDINGS" > "$tmp"
  chmod 644 "$tmp"
  mv "$tmp" "$FINDINGS"
}

run_wizard() {

# Run from the repo root, whatever the caller's directory.
cd "$(dirname "$0")/.."
ENV_FILE=".env.sponsored-sign-probe"

TOTAL_STAGES=6

banner "Issue #$ISSUE: sponsored MPC sign through NEP-366 (testnet)"

# ── 1. Local stack and relayer key ────────────────────────────────────────
stage "Start Herald locally on testnet"
if [[ ! -f "$PROBE_ROUTE" || ! -f "$PROBE_SERVER" ]]; then
  warn "The probe page is missing ($PROBE_ROUTE, $PROBE_SERVER)."
  warn "Ask your agent to recreate it, then re-run this wizard."
  exit 1
fi
for f in apps/web/.dev.vars apps/facilitator/.dev.vars; do
  if [[ -f "$f" ]]; then
    note "✓ $f exists"
  else
    warn "$f is missing: copy ${f}.example and fill it in (testnet RPC URLs)."
    pause "Press Enter once it's in place"
  fi
done
say "The local Worker serves Herald testnet (HERALD_ENV=testnet in apps/web/wrangler.jsonc)."
if confirm "Apply the local D1 migrations now (vp run db:migrate:local)?"; then
  vp run db:migrate:local || warn "The migrations didn't apply. Fix that before signing in."
fi
printf '\n'

say "The probe relays with Herald's testnet relayer. Its key goes into $DEV_VARS first,"
say "because the dashboard reads that file when it starts."
RELAYER=$(relayer_account || true)
if [[ -z "$RELAYER" ]]; then
  warn "No testnet relayer is recorded in $RELAYER_ENV."
  warn "Run scripts/near-relayer-wizard.sh testnet to provision it, then re-run this wizard."
  exit 1
fi
if [[ ! "$RELAYER" =~ ^[0-9a-f]{64}$ ]]; then
  warn "\"$RELAYER\" in $RELAYER_ENV isn't an implicit account id (64 hex characters)."
  warn "The probe names the relayer by its key, so it must be the implicit account the relayer wizard made."
  exit 1
fi
KEY_FILE=$(key_file "$RELAYER")
if [[ ! -f "$KEY_FILE" ]]; then
  warn "The relayer's key file $KEY_FILE is missing on this machine."
  warn "Copy it here from the machine that ran scripts/near-relayer-wizard.sh, then re-run."
  exit 1
fi
say "Relayer account: $RELAYER"
say "Public key:      $(public_key_of "$KEY_FILE")"
say "Explorer:        $EXPLORER/address/$RELAYER"
if command -v near >/dev/null 2>&1; then
  note "Balance:"
  near tokens "$RELAYER" view-near-balance network-config testnet now 2>&1 | sed 's/^/    /' || true
fi
note "Each sponsored sign costs the relayer about 0.001 NEAR. The whole probe costs well under 0.05 NEAR."
note "The deployed facilitator uses the same key. Its NearChainQueue can hit one stale nonce"
note "while the probe runs; it retries that on its own."
write_env RELAYER_ACCOUNT "$RELAYER"
if confirm "Copy the relayer's private key into $DEV_VARS as $PROBE_KEY_NAME?"; then
  if install_probe_key "$KEY_FILE" "$RELAYER"; then
    printf '  %s✓ wrote%s %s → %s (value not shown)\n' "$GREEN" "$RESET" "$PROBE_KEY_NAME" "$DEV_VARS"
  else
    warn "Couldn't write $PROBE_KEY_NAME. The probe can't relay without it."
    exit 1
  fi
elif has_probe_key; then
  note "Kept the $PROBE_KEY_NAME already in $DEV_VARS."
else
  warn "Without $PROBE_KEY_NAME the probe can't relay. Re-run the wizard when you want to."
  exit 1
fi
printf '\n'

say "Start both apps, each in its own terminal, and leave them running:"
step "vp -C apps/facilitator run dev     (facilitator, http://localhost:8787)"
step "vp -C apps/web dev                 (dashboard, $APP_URL)"
note "If the dashboard was already running, restart it so it reads $PROBE_KEY_NAME."
pause "Press Enter once both are up"
until curl -fsS "$APP_URL/api/health" >/dev/null 2>&1; do
  warn "$APP_URL/api/health doesn't answer yet."
  pause "Press Enter to check again"
done
note "✓ dashboard is up at $APP_URL"
pause "Press Enter to continue"

# ── 2. Meteor Wallet ──────────────────────────────────────────────────────
stage "Meteor Wallet on testnet"
say "You need a NEAR testnet account in Meteor Wallet with a full-access key."
say "The account must exist on chain: a delegate action is checked against its access key."
say "The relayer pays the gas, so 1 testnet NEAR on the account is plenty."
open_url "https://docs.near.org/getting-started/faucet"
step "Create or pick a testnet account and send it testnet NEAR from the faucet."
if confirm "Do you need to install Meteor Wallet or switch it to testnet first?"; then
  open_url "https://meteorwallet.app"
  step "Install it, switch it to testnet, and add your funded testnet account with its full-access key."
  pause "Press Enter when it's ready"
fi
open_url "$APP_URL/overview"
step "If you're signed in, click Sign out (top right) so the wallet connection resets."
step "On the sign-in page, pick Meteor Wallet and approve the sign-in message."
note "Signing in registers the account as a Provider in your local database only."
pause "Press Enter once you're on the dashboard, signed in through Meteor Wallet"

# ── 3. Check one ──────────────────────────────────────────────────────────
stage "Check one: one sponsored sign"
probe_check one

# ── 4. Check three ────────────────────────────────────────────────────────
stage "Check three: one request, three delegate actions"
say "Same page, same wallet: no need to sign in again."
probe_check three

# ── 5. Findings ───────────────────────────────────────────────────────────
stage "Write the findings"
if passes one && passes three; then
  verdict_kind=both
  verdict="Meteor signs sponsored \`sign\` calls, alone and three in one request, and all of them landed. ADR 0010 stands; #48, #49 and #50 can go ahead."
elif passes one; then
  verdict_kind=one
  verdict="A single sponsored Sweep works on Meteor, but three delegate actions in one request didn't all land ($(summary three)). #48 can go ahead. #49 must not rely on one signDelegateActions request for several Sweeps: fall back to one request per Sweep, or to today's path."
else
  verdict_kind=none
  verdict="Meteor didn't produce a usable sponsored \`sign\` ($(summary one)). ADR 0010 must be rewritten to record that Herald can't sponsor the sign gas with Meteor, and #48, #49 and #50 updated."
fi
if [[ "$verdict_kind" != none ]] && ! one_approval one; then
  verdict+=" Note: check one took $(saved PROBE_ONE_PROMPTS) approval prompt(s), not 1."
fi
if [[ "$verdict_kind" == both ]] && ! one_approval three; then
  verdict+=" Check three took $(saved PROBE_THREE_PROMPTS) approval prompt(s), so #49's one approval for every chain doesn't hold on Meteor."
fi
if [[ "$verdict_kind" == both ]]; then
  if nonces_ascending "$(saved PROBE_THREE_LINE)"; then
    verdict+=" Meteor numbers the nonces in request order, so #49 puts Solana's delegate action first in the request to have it relayed first."
  else
    verdict+=" Meteor doesn't number the nonces in request order, so #49 can't get Solana's relayed first by putting it first in the request: the relayer must follow the nonces."
  fi
fi

section=$(mktemp)
write_section "$section"
if has_markers; then
  splice_section "$section"
  printf '  %s✓ wrote%s the Meteor section of %s, between its markers\n' "$GREEN" "$RESET" "$FINDINGS"
else
  if [[ -f "$FINDINGS" ]]; then
    warn "$FINDINGS has no $MARKER_START ... $MARKER_END section."
  else
    warn "$FINDINGS is missing. Writing it with only the Meteor section."
  fi
  { printf '\n%s\n' "$MARKER_START"; cat "$section"; printf '%s\n' "$MARKER_END"; } >> "$FINDINGS"
  printf '  %s✓ appended%s the Meteor section, with markers, to the end of %s\n' "$GREEN" "$RESET" "$FINDINGS"
fi
rm -f "$section"
printf '\n'
say "$verdict"
pause "Press Enter to continue"

# ── 6. Ticket, ADR and clean-up ───────────────────────────────────────────
stage "Post on #$ISSUE, check the ADR, and remove the probe"
comment_url=""
if [[ -f "$FINDINGS" ]] && confirm "Post $FINDINGS as a comment on $REPO#$ISSUE?"; then
  if gh_ready && comment_url=$(gh issue comment "$ISSUE" --repo "$REPO" --body-file "$FINDINGS"); then
    printf '  %s✓ commented%s on %s#%s %s\n' "$GREEN" "$RESET" "$REPO" "$ISSUE" "$comment_url"
  else
    comment_url=""
    SKIPPED+=("comment on #$ISSUE: gh issue comment $ISSUE --repo $REPO --body-file $FINDINGS")
    warn "Couldn't comment with gh. Do it by hand later."
  fi
fi
printf '\n'
if [[ "$verdict_kind" == both ]]; then
  note "✓ The probe passed, which is what $ADR assumes."
  if [[ ! -f "$ADR" ]]; then
    warn "$ADR is missing. Ask your agent to write it."
  elif grep -q '^status: proposed$' "$ADR" && confirm "Mark $ADR accepted?"; then
    node -e '
      const fs = require("node:fs");
      const file = process.argv[1];
      fs.writeFileSync(file, fs.readFileSync(file, "utf8").replace(/^status: proposed$/m, "status: accepted"));
    ' "$ADR" && note "✓ $ADR is now accepted"
  fi
else
  warn "THE PROBE DID NOT FULLY PASS."
  warn "$ADR assumes it did. Amend it before #48, #49 or #50 go ahead."
  link="${comment_url:-https://github.com/$REPO/issues/$ISSUE}"
  body="Heads-up from the sponsored sign probe on #$ISSUE: it didn't fully pass. $verdict Findings: $link (also in $FINDINGS). $ADR assumes the probe passes and needs amending before this goes ahead."
  if confirm "Post a short comment on #48, #49 and #50 linking the findings?"; then
    for n in 48 49 50; do
      if gh_ready && gh issue comment "$n" --repo "$REPO" --body "$body" >/dev/null; then
        printf '  %s✓ commented%s on %s#%s\n' "$GREEN" "$RESET" "$REPO" "$n"
      else
        SKIPPED+=("comment on #$n linking the findings ($link)")
        warn "Couldn't comment on #$n with gh. Do it by hand later."
      fi
    done
  else
    SKIPPED+=("tell #48, #49 and #50 that the probe didn't fully pass ($link)")
  fi
  SKIPPED+=("amend $ADR to match the findings")
fi
printf '\n'
say "The probe page is throwaway and must not be committed."
if confirm "Delete it now ($PROBE_ROUTE, $PROBE_SERVER) and restore $ROUTE_TREE from git?"; then
  rm -f "$PROBE_ROUTE" "$PROBE_SERVER"
  if git checkout -- "$ROUTE_TREE"; then
    note "✓ probe removed. If the dashboard is still running it regenerates the route tree, matching git."
  else
    SKIPPED+=("git checkout -- $ROUTE_TREE")
    warn "Couldn't restore $ROUTE_TREE. Run: git checkout -- $ROUTE_TREE"
  fi
else
  SKIPPED+=("delete $PROBE_ROUTE and $PROBE_SERVER, then: git checkout -- $ROUTE_TREE")
fi
if confirm "Remove $PROBE_KEY_NAME (the relayer's private key) from $DEV_VARS?"; then
  if remove_probe_key && ! has_probe_key; then
    note "✓ removed $PROBE_KEY_NAME from $DEV_VARS"
  else
    SKIPPED+=("remove the $PROBE_KEY_NAME line from $DEV_VARS")
    warn "Couldn't remove it. Delete the $PROBE_KEY_NAME line from $DEV_VARS by hand."
  fi
else
  SKIPPED+=("remove the $PROBE_KEY_NAME line from $DEV_VARS")
fi
note "Restart the dashboard (vp -C apps/web dev) so it no longer holds the relayer key."
if [[ "$verdict_kind" == both ]]; then
  note "Remember to commit $FINDINGS and $ADR."
else
  note "Remember to commit $FINDINGS, and $ADR once it's amended."
fi
note "Your answers stay in $ENV_FILE (gitignored); delete it when done."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
